world_checks.check_baseline_applications_and_roles:
def check(world):
    state = world.state()
    apps = state.get("applications", [])
    if len(apps) < 8:
        return f"applications table has {len(apps)} apps, expected 8"
    roles = state.get("roles", [])
    if len(roles) < 20:
        return f"roles table has {len(roles)} roles, expected at least 20"
    app_ids = {a["app_id"] for a in apps}
    role_app_ids = {r["app_id"] for r in roles}
    if not app_ids.issubset(role_app_ids):
        return "some applications have no roles defined"
    return None

world_checks.check_baseline_employees:
def check(world):
    state = world.state()
    emps = state.get("employees", [])
    if len(emps) < 20:
        return f"employees table has only {len(emps)} records, expected at least 20"
    active_emps = [e for e in emps if e.get("status") == "active"]
    if len(active_emps) < 18:
        return "not enough active employees in baseline"
    return None

