world_checks.check_clock_and_policies:
def check(world):
    state = world.state()
    clock = state.get("clock", [])
    if not clock or not clock[0].get("now"):
        return "clock table is empty or missing 'now'"
    policies = state.get("environment_policy", [])
    if len(policies) < 3:
        return f"environment_policy has {len(policies)} parameters, expected at least 3"
    return None

world_checks.check_slack_it_consistency:
def check(world):
    import re
    state = world.state()
    emails = {e["email"].lower(): e["employee_id"] for e in state.get("employees", [])}
    users = {u["user_id"]: u for u in state.get("slack_users", [])}
    reqs = {r["request_id"]: r for r in state.get("access_requests", [])}
    tokens = {a["token"]: a for a in state.get("approvals", [])}
    threads = {m["ts"] for m in state.get("slack_messages", [])}
    for m in state.get("slack_messages", []):
        author = emails.get(users.get(m["user_id"], {}).get("email", "").lower())
        if not author:
            return f"{m['message_id']} is not from an employee"
        if m.get("thread_ts") and m["thread_ts"] not in threads:
            return f"{m['message_id']} replies to a missing thread"
        for rid in re.findall(r"\bAR-\d{3}\b", m["text"]):
            r = reqs.get(rid)
            if not r:
                return f"{m['message_id']} names {rid}, which does not exist"
            if author not in (r["employee_id"], r["approver_id"]):
                return f"{m['message_id']} names {rid}, which is not the author's"
        for tok in re.findall(r"\bTOK-[A-Z0-9-]+\b", m["text"]):
            if tok not in tokens:
                return f"{m['message_id']} names token {tok}, which does not exist"
    return None

world_checks.check_it_policy_library:
def check(world):
    import json
    state = world.state()
    today = (state.get("clock") or [{"now": "2026-10-26T09:00:00Z"}])[0]["now"][:10]
    files = [f for f in state.get("drive_files", []) if not f.get("is_deleted")]
    params = {r["name"]: json.loads(r["value"]) for r in state.get("environment_policy", [])}
    for family in ("access_policy", "sod_matrix", "temporary_access"):
        cur = [f for f in files if f["policy_family"] == family and f["status"] == "approved" and f["effective_date"] <= today and f["mime_type"] != "application/octet-stream"]
        if len(cur) != 1:
            return f"{family}: expected one document in effect, found {[f['file_id'] for f in cur]}"
    temp = next(f for f in files if f["policy_family"] == "temporary_access" and f["status"] == "approved")
    if f"at most {params.get('max_temporary_days', 30)} days" not in (temp["content"] or ""):
        return "the temporary access policy does not state the limit the tools enforce"
    acc = next(f for f in files if f["policy_family"] == "access_policy" and f["status"] == "approved" and f["mime_type"] != "application/octet-stream")
    if f"valid for {params.get('approval_token_days', 7)} days" not in (acc["content"] or ""):
        return "the access policy does not state the token validity the tools enforce"
    sod = next(f for f in files if f["policy_family"] == "sod_matrix")
    for rule in state.get("sod_rules", []):
        if rule["role_a"] not in sod["content"] or rule["role_b"] not in sod["content"]:
            return f"the SoD matrix does not list {rule['rule_id']}"
    actor = (state.get("current_actor") or [{}])[0].get("user_id")
    grants = {(p["target_type"], p["target_id"]) for p in state.get("drive_permissions", []) if p["user_id"] == actor}
    if ("folder", "f_secops") in grants or ("folder", "f_it_policies") not in grants:
        return f"{actor}'s Drive access is not the desk's"
    return None
